let today='';let habits=[];let revs={};
const list=document.getElementById('list');
const msg=document.getElementById('msg');
const nameIn=document.getElementById('name');
function prev(d){const p=d.split('-').map(Number);const t=new Date(Date.UTC(p[0],p[1]-1,p[2]-1));return t.toISOString().slice(0,10);}
function streak(dates){const s=new Set(dates);if(!s.has(today))return 0;let n=0,d=today;while(s.has(d)){n++;d=prev(d);}return n;}
function render(focusId){
 list.textContent='';
 document.getElementById('empty').hidden=habits.length>0;
 for(const h of habits){
  const dates=Array.isArray(h.doneDates)?h.doneDates:[];
  const isDone=dates.includes(today);
  const li=document.createElement('li');
  li.setAttribute('data-hook','habit');
  const nm=document.createElement('span');nm.className='hname';nm.textContent=h.name;
  const st=document.createElement('span');st.className='streak';
  const n=document.createElement('span');n.className='n';n.setAttribute('data-hook','habit-streak');n.textContent=String(streak(dates));
  st.appendChild(n);st.appendChild(document.createTextNode(isDone?' day streak':' day streak · not done yet today'));
  const b=document.createElement('button');b.type='button';b.setAttribute('data-hook','habit-done');b.dataset.id=h.id;
  b.textContent=isDone?'Done today ✓':'Mark done today';
  if(isDone){b.className='done';b.setAttribute('aria-label','Done today: '+h.name);}else{b.setAttribute('aria-label','Mark done today: '+h.name);}
  b.addEventListener('click',()=>markDone(h.id));
  li.appendChild(nm);li.appendChild(st);li.appendChild(b);list.appendChild(li);
  if(focusId===h.id)b.focus();
 }
}
async function load(focusId){
 const r=await tessera.call('data.read',{});
 habits=Array.isArray(r.data.habits)?r.data.habits:[];
 revs=(r.revisions&&r.revisions.habits)||{};
 render(focusId);
}
async function markDone(id){
 msg.textContent='';
 const h=habits.find(x=>x.id===id);if(!h)return;
 const dates=Array.isArray(h.doneDates)?h.doneDates:[];
 if(dates.includes(today))return;
 try{
  await tessera.call('data.patch',{operations:[{op:'replace',collection:'habits',id:id,revisionCount:revs[id],fields:{doneDates:dates.concat([today])}}]});
  await load(id);
 }catch(e){msg.textContent='Could not save that. Please try again.';await load(id);}
}
async function addHabit(){
 msg.textContent='';
 const v=nameIn.value.trim();
 if(!v){msg.textContent='Type a name for the habit first.';nameIn.focus();return;}
 try{
  await tessera.call('data.patch',{operations:[{op:'add',collection:'habits',record:{name:v,doneDates:[]}}]});
  nameIn.value='';await load();nameIn.focus();
 }catch(e){msg.textContent='Could not add the habit. What you typed is still there.';}
}
document.getElementById('add').addEventListener('click',addHabit);
nameIn.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addHabit();}});
(async()=>{
 try{
  const c=await tessera.call('clock.now',{});
  today=c.date;
  document.getElementById('today').textContent='Today is '+today+'.';
  await load();
 }catch(e){msg.textContent='Could not load your habits.';}
})();

